// src/components/AdminDashboard.js
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios'; // Keep axios for now, but prefer authenticated API client
import { useAuth } from '../context/AuthContext'; // Assuming this path is correct

// --- Import API service functions ---
// FIX: Corrected import paths to resolve relative to the current file
import { fetchCustomers, addCustomer as apiAddCustomer } from '../api/customers';
import { fetchInventoryItems } from '../api/inventory';
import { recordSale } from '../api/sales';

const AdminDashboard = () => {
  // --- State for User Management ---
  const [users, setUsers] = useState([]);
  const [usersLoading, setUsersLoading] = useState(true);

  // --- State for Inventory Management (Add Item) ---
  const [inventoryItems, setInventoryItems] = useState([]); // For displaying inventory and selecting for sale
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');
  const [newItemQuantity, setNewItemQuantity] = useState('');
  const [inventoryLoading, setInventoryLoading] = useState(true);

  // --- State for Sales Entry ---
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState(''); // State for selected customer ID
  const [showAddCustomerForm, setShowAddCustomerForm] = useState(false); // To toggle the new customer form
  const [saleItems, setSaleItems] = useState([]); // Items currently in the sale
  const [discountAmount, setDiscountAmount] = useState(0);
  const [discountPercentage, setDiscountPercentage] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [customerFetchError, setCustomerFetchError] = useState(''); // Specific error for customer fetching
  const [saleError, setSaleError] = useState('');             // Specific error for sale submission
  const [saleLoading, setSaleLoading] = useState(false);

  const [selectedItemId, setSelectedItemId] = useState(''); // FIX: State for selected item in sale
  const [currentQuantity, setCurrentQuantity] = useState(1); // FIX: State for quantity input in sale

  const newCustomerFormRef = useRef(null); // For focusing the select after adding a customer

  // --- Auth Context ---
  const { currentUser, logout } = useAuth();
  // If you have an authenticated API client: const { api } = useAuth();

  // --- Effects to Fetch Initial Data ---
  useEffect(() => {
    fetchUsers();
    fetchInventory();
    fetchCustomersData(); // Fetch customers for the sales entry
  }, []);

  // --- User Management Functions ---
  const fetchUsers = async () => {
    setUsersLoading(true);
    setError(null); // This refers to the general error state
    try {
      // Use authenticated API client if available: const response = await api.get('/admin/users');
      const response = await axios.get('/api/admin/users');
      setUsers(response.data.data);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to fetch users. Please try again.');
    } finally {
      setUsersLoading(false);
    }
  };

  const updateUserRole = async (userId, newRole) => {
    try {
      // Use authenticated API client if available: await api.put(`/admin/users/${userId}/role`, { role: newRole });
      await axios.put(`/api/admin/users/${userId}/role`, {
        role: newRole
      });
      fetchUsers();
    } catch (err) {
      console.error('Error updating user role:', err);
      setError('Failed to update user role.'); // Using general error state here is okay
    }
  };

  const deleteUser = async (userId) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      try {
        // Use authenticated API client if available: await api.delete(`/admin/users/${userId}`);
        await axios.delete(`/api/admin/users/${userId}`);
        fetchUsers();
      } catch (err) {
        console.error('Error deleting user:', err);
        setError('Failed to delete user.'); // Using general error state here is okay
      }
    }
  };

  // --- Inventory Management Functions (for adding new inventory items) ---
  const fetchInventory = async () => {
    setInventoryLoading(true);
    setError(null); // Refers to the general error state
    try {
      // Use authenticated API client if available: const response = await api.get('/inventory'); // Or /admin/inventory
      const response = await axios.get('/api/admin/inventory');
      setInventoryItems(response.data.data);
    } catch (err) {
      console.error('Error fetching inventory:', err);
      setError('Failed to fetch inventory. Please try again.'); // Using general error state
    } finally {
      setInventoryLoading(false);
    }
  };

  // Handler for adding a NEW inventory item (different from adding item to sale)
  const handleAddNewInventoryItem = async (e) => {
    e.preventDefault();
    if (!newItemName || !newItemPrice || !newItemQuantity) {
      alert('Please fill in all fields for the new inventory item.');
      return;
    }

    const price = parseFloat(newItemPrice);
    const quantity = parseInt(newItemQuantity, 10);

    if (isNaN(price) || price < 0) {
      alert('Please enter a valid price (non-negative number).');
      return;
    }
    if (isNaN(quantity) || quantity < 0) {
      alert('Please enter a valid quantity (non-negative integer).');
      return;
    }

    try {
      // Use authenticated API client if available: const response = await api.post('/admin/inventory', { ... });
      const response = await axios.post('/api/admin/inventory', {
        name: newItemName,
        price: price,
        quantity: quantity,
      });
      fetchInventory(); // Refresh the inventory list
      setNewItemName('');
      setNewItemPrice('');
      setNewItemQuantity('');
      alert('Item added successfully!');
    } catch (err) {
      console.error('Error adding item:', err);
      setError('Failed to add item.'); // Using general error state
    }
  };

  // --- Sales Entry Functions ---

  const fetchCustomersData = async () => {
    setCustomerFetchError(''); // Use specific error state
    try {
      // Use authenticated API client if available: const fetchedCustomers = await api.get('/customers');
      const fetchedCustomers = await fetchCustomers(); // Correctly calls the imported function
      setCustomers(fetchedCustomers);
    } catch (err) {
      console.error("Error fetching customers:", err);
      setCustomerFetchError('Failed to load customers. Please try again.'); // Use specific error state
    }
  };

  const handleCustomerChange = (e) => { // Changed to use event object for consistency
    setSelectedCustomerId(e.target.value);
    setSaleError(''); // Clear any previous sale error when customer changes
  };

  const handleAddNewCustomerClick = () => {
    setShowAddCustomerForm(true);
  };

  const handleCloseAddCustomerForm = () => {
    setShowAddCustomerForm(false);
  };

  const handleCustomerAdded = (newCustomer) => {
    setCustomers(prevCustomers => [...prevCustomers, newCustomer].sort((a, b) => a.name.localeCompare(b.name)));
    setSelectedCustomerId(newCustomer._id); // Select the newly added customer
    setShowAddCustomerForm(false);
  };

  const handleAddItemToSale = (itemToAdd) => {
    const existingItemIndex = saleItems.findIndex(saleItem => saleItem.itemId === itemToAdd.itemId);
    let updatedSaleItems;

    if (existingItemIndex > -1) {
      updatedSaleItems = [...saleItems];
      const existingItem = updatedSaleItems[existingItemIndex];
      const newQuantity = existingItem.quantity + itemToAdd.quantity;

      const currentInventoryItem = inventoryItems.find(invItem => invItem._id === itemToAdd.itemId);
      if (currentInventoryItem && newQuantity > currentInventoryItem.quantity) {
        alert(`Cannot add more. Insufficient stock for ${itemToAdd.name}. Available: ${currentInventoryItem.quantity}`);
        return;
      }
      updatedSaleItems[existingItemIndex] = { ...existingItem, quantity: newQuantity };
    } else {
      updatedSaleItems = [...saleItems, itemToAdd];
    }

    setSaleItems(updatedSaleItems);
    setSaleError(''); // Clear sale error on successful add
  };

  const handleRemoveSaleItem = (indexToRemove) => {
    setSaleItems(saleItems.filter((_, index) => index !== indexToRemove));
  };

  const handleSubmitSale = async () => {
    if (!selectedCustomerId) {
      setSaleError('Please select a customer.');
      return;
    }
    if (saleItems.length === 0) {
      setSaleError('Please add items to the sale.');
      return;
    }

    setSaleLoading(true);
    setSaleError('');

    const saleData = {
      customerId: selectedCustomerId,
      items: saleItems.map(item => ({
        itemId: item.itemId,
        quantity: item.quantity,
        priceAtSale: item.priceAtSale,
        name: item.name
      })),
      discountAmount: discountAmount,
      discountPercentage: discountPercentage,
      paymentMethod: paymentMethod,
    };

    try {
      // Use authenticated API client if available: const response = await api.post('/sales/entry', saleData);
      const response = await axios.post('/api/sales/entry', saleData);
      alert(`Sale recorded successfully! Sale ID: ${response.data._id}`);
      // Reset form after successful submission
      setSelectedCustomerId('');
      setSaleItems([]);
      setDiscountAmount(0);
      setDiscountPercentage(0);
      setPaymentMethod('cash');
      // Re-fetch customers and inventory
      fetchCustomersData();
      fetchInventory();
    } catch (error) {
      console.error('Sale Submission Error:', error);
      setSaleError(error.response?.data?.message || 'Failed to record sale. Please check stock and try again.');
    } finally {
      setSaleLoading(false);
    }
  };

  // --- Calculations for Summary ---
  let subtotal = saleItems.reduce((sum, item) => sum + item.priceAtSale * item.quantity, 0);
  let totalAfterDiscount = subtotal;

  if (discountPercentage > 0) {
    const percentageDiscountValue = (subtotal * discountPercentage) / 100;
    totalAfterDiscount = subtotal - percentageDiscountValue;
  }
  if (discountAmount > 0) {
    totalAfterDiscount = totalAfterDiscount - discountAmount;
  }
  totalAfterDiscount = Math.max(0, totalAfterDiscount);

  // --- Combined Loading State ---
  const overallLoading = usersLoading || inventoryLoading || saleLoading; // Added saleLoading

  if (overallLoading) {
    return <div className="flex justify-center items-center h-screen">Loading...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navbar */}
      <nav className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-red-600">Admin Dashboard</h1>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-gray-700">Welcome, {currentUser?.username || 'Admin'}</span>
              <button onClick={logout} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md text-sm font-medium">Logout</button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-6 sm:px-0">

          {/* Display Errors */}
          {(error || customerFetchError || saleError) && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-8" role="alert">
              <strong className="font-bold">Error:</strong>
              <span className="block sm:inline"> {error || customerFetchError || saleError}</span>
              <span className="absolute top-0 bottom-0 right-0 px-4 py-3">
                <button onClick={() => { setError(null); setCustomerFetchError(null); setSaleError(null); }} className="text-red-700 hover:text-red-900">
                  <svg className="fill-current h-6 w-6 text-red-500" role="button" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><title>Close</title><path d="M14.348 14.849c-0.469 0.469-1.229 0.469-1.697 0L10 11.819l-2.651 3.029c-0.469 0.469-1.229 0.469-1.697 0-0.469-0.469-0.469-1.229 0-1.697l2.651-3.029L5.651 5.651c-0.469-0.469-0.469-1.229 0-1.697c0.469-0.469 1.229-0.469 1.697 0L10 8.181l2.651-3.029c0.469-0.469 1.229-0.469 1.697 0c0.469 0.469 0.469 1.229 0 1.697L11.819 10l3.029 2.651c0.469 0.469 0.469 1.229 0 1.697z"/></svg>
                </button>
              </span>
            </div>
          )}

          {/* Stats Overview */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0"><div className="h-10 w-10 bg-blue-500 rounded-full flex items-center justify-center"><span className="text-white">👥</span></div></div>
                  <div className="ml-5 w-0 flex-1">
                    <dl><dt className="text-sm font-medium text-gray-500 truncate">Total Users</dt><dd className="text-2xl font-bold text-gray-900">{users.length}</dd></dl>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0"><div className="h-10 w-10 bg-green-500 rounded-full flex items-center justify-center"><span className="text-white">📦</span></div></div>
                  <div className="ml-5 w-0 flex-1">
                    <dl><dt className="text-sm font-medium text-gray-500 truncate">Total Inventory Items</dt><dd className="text-2xl font-bold text-gray-900">{inventoryItems.length}</dd></dl>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Add New Item Form */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900">Add New Inventory Item</h3>
              <form onSubmit={handleAddNewInventoryItem} className="mt-5 grid grid-cols-1 gap-y-6 sm:grid-cols-3">
                <div>
                  <label htmlFor="itemName" className="block text-sm font-medium text-gray-700">Item Name</label>
                  <div className="mt-1"><input type="text" id="itemName" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} required className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2" placeholder="e.g., Laptop" /></div>
                </div>
                <div>
                  <label htmlFor="itemPrice" className="block text-sm font-medium text-gray-700">Price</label>
                  <div className="mt-1"><input type="number" id="itemPrice" value={newItemPrice} onChange={(e) => setNewItemPrice(e.target.value)} required min="0" step="0.01" className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2" placeholder="e.g., 1200.50" /></div>
                </div>
                <div>
                  <label htmlFor="itemQuantity" className="block text-sm font-medium text-gray-700">Quantity</label>
                  <div className="mt-1"><input type="number" id="itemQuantity" value={newItemQuantity} onChange={(e) => setNewItemQuantity(e.target.value)} required min="0" className="shadow-sm focus:ring-red-500 focus:border-red-500 block w-full sm:text-sm border-gray-300 rounded-md p-2" placeholder="e.g., 50" /></div>
                </div>
                <div className="sm:col-span-3 flex items-end">
                  <button type="submit" className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500">Add Item</button>
                </div>
              </form>
            </div>
          </div>

          {/* --- NEW SECTION: Sales Entry Form --- */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">Record New Sale</h3>

              {/* Customer Selection / Add New Customer */}
              <div className="mb-6 p-4 border border-gray-200 rounded-md bg-gray-50">
                <div className="flex items-center mb-4">
                  <label htmlFor="customerSelect" className="block text-sm font-medium text-gray-700 mr-4">Customer:</label>
                  <select
                    ref={newCustomerFormRef}
                    id="customerSelect"
                    value={selectedCustomerId || ''}
                    onChange={handleCustomerChange}
                    className="border rounded-md p-2 text-sm w-64"
                    disabled={customers.length === 0 || customerFetchError || loadingCustomers} // Disable if no customers or error
                  >
                    <option value="" disabled>Select a customer</option>
                    {customers.map((customer) => (
                      <option key={customer._id} value={customer._id}>
                        {customer.name} {customer.email ? `(${customer.email})` : ''}
                      </option>
                    ))}
                  </select>
                  <button
                    onClick={handleAddNewCustomerClick}
                    className="ml-4 px-3 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                  >
                    New Customer
                  </button>
                </div>

                {/* Inline Add Customer Form */}
                {showAddCustomerForm && (
                  <div className="p-4 border border-gray-300 rounded-md mt-4 bg-gray-100">
                    <div className="flex justify-between items-center mb-4">
                      <h4 className="text-md font-semibold">Add New Customer</h4>
                      <button onClick={handleCloseAddCustomerForm} className="text-gray-500 hover:text-gray-700">&times;</button>
                    </div>
                    <form onSubmit={(e) => {
                      e.preventDefault();
                      const form = e.target;
                      const name = form.elements.customerName.value;
                      const email = form.elements.customerEmail.value;
                      const phone = form.elements.customerPhone.value;
                      if (!name) { alert('Customer name is required.'); return; }
                      // Using apiAddCustomer from imported API functions
                      apiAddCustomer({ name, email, phone }).then(handleCustomerAdded).catch(err => {
                        console.error("Inline add customer error:", err.response?.data?.message || err.message);
                        alert("Failed to add customer: " + (err.response?.data?.message || 'Unknown error'));
                      });
                    }}>
                      <div className="mb-2">
                        <label htmlFor="customerName" className="block text-sm font-medium text-gray-700">Name</label>
                        <input ref={newCustomerFormRef} type="text" id="customerName" required className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm" />
                      </div>
                      <div className="mb-2">
                        <label htmlFor="customerEmail" className="block text-sm font-medium text-gray-700">Email</label>
                        <input type="email" id="customerEmail" className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm" />
                      </div>
                      <div className="mb-2">
                        <label htmlFor="customerPhone" className="block text-sm font-medium text-gray-700">Phone</label>
                        <input type="tel" id="customerPhone" className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm" />
                      </div>
                      <div className="text-right">
                        <button type="submit" className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">Add & Select</button>
                      </div>
                    </form>
                  </div>
                )}
              </div>

              {/* Item Selector for Sale */}
              <div className="mb-6 p-4 border border-gray-200 rounded-md bg-gray-50">
                <h4 className="text-lg font-medium text-gray-700 mb-3">Add Items to Sale</h4>
                <div className="flex flex-wrap items-center gap-4">
                  <label htmlFor="itemSelect" className="block text-sm font-medium text-gray-700">Item:</label>
                  <select
                    id="itemSelect"
                    value={selectedItemId}
                    onChange={(e) => {
                      setSelectedItemId(e.target.value);
                      setSaleError(''); // Clear sale error on item change
                      const item = inventoryItems.find(i => i._id === e.target.value);
                      // Adjust quantity if the new item's stock is less than current quantity
                      if (item && item.quantity < currentQuantity) {
                        setCurrentQuantity(item.quantity > 0 ? item.quantity : 1);
                      }
                    }}
                    className="border rounded-md p-2 text-sm w-64"
                    disabled={inventoryItems.length === 0 || inventoryLoading || customerFetchError}
                  >
                    <option value="" disabled>Select an item</option>
                    {inventoryItems.map((item) => (
                      <option key={item._id} value={item._id} disabled={item.quantity <= 0}>
                        {item.name} - ${item.price.toFixed(2)} {item.quantity <= 0 ? '(Out of Stock)' : `(Qty: ${item.quantity})`}
                      </option>
                    ))}
                  </select>

                  <label htmlFor="quantityInput" className="block text-sm font-medium text-gray-700">Qty:</label>
                  <input
                    type="number" id="quantityInput" value={currentQuantity}
                    onChange={(e) => {
                      const num = parseInt(e.target.value, 10);
                      setCurrentQuantity(isNaN(num) || num < 1 ? 1 : num);
                      setSaleError(''); // Clear sale error on quantity change
                    }}
                    min="1" className="w-20 p-2 border rounded-md text-sm"
                  />
                  <button
                    onClick={() => {
                      if (!selectedItemId || currentQuantity < 1) { setSaleError('Select item and valid quantity.'); return; }
                      const selectedItem = inventoryItems.find(item => item._id === selectedItemId);
                      if (!selectedItem) { setSaleError('Selected item not found.'); return; } // Should not happen if dropdown is populated correctly
                      if (selectedItem.quantity < currentQuantity) {
                        alert(`Cannot add more. Insufficient stock for ${selectedItem.name}. Available: ${selectedItem.quantity}`);
                        return;
                      }
                      handleAddItemToSale({
                        itemId: selectedItem._id,
                        name: selectedItem.name,
                        quantity: currentQuantity,
                        priceAtSale: selectedItem.price,
                      });
                      // Reset selector and quantity for next item
                      setSelectedItemId('');
                      setCurrentQuantity(1);
                    }}
                    disabled={!selectedItemId || currentQuantity < 1 || !selectedItem || inventoryItems.find(i => i._id === selectedItemId)?.quantity < currentQuantity}
                    className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                  >
                    Add Item
                  </button>
                </div>
              </div>

              {/* Current Sale Items Table */}
              <div className="mb-6">
                <h4 className="text-lg font-medium text-gray-700 mb-3">Current Sale Items</h4>
                {saleItems.length === 0 ? (
                  <p className="text-center text-gray-500 py-4">No items added to the sale yet.</p>
                ) : (
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Item</th>
                        <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Unit Price</th>
                        <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                        <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Line Total</th>
                        <th scope="col" className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {saleItems.map((item, index) => (
                        <tr key={index} className="bg-white hover:bg-gray-100">
                          <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-900">{item.name}</td>
                          <td className="px-4 py-2 whitespace-nowrap text-sm text-gray-500">${item.priceAtSale.toFixed(2)}</td>
                          <td className="px-4 py-2 whitespace-nowrap text-sm text-gray-900">{item.quantity}</td>
                          <td className="px-4 py-2 whitespace-nowrap text-sm text-gray-700">${(item.priceAtSale * item.quantity).toFixed(2)}</td>
                          <td className="px-4 py-2 whitespace-nowrap text-right text-sm font-medium">
                            <button onClick={() => handleRemoveSaleItem(index)} className="text-red-600 hover:text-red-900 focus:outline-none focus:ring-2 focus:ring-red-500 rounded">Remove</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>

              {/* Discounts and Payment Method */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6 p-4 border border-gray-200 rounded-md bg-gray-50">
                <div>
                  <label htmlFor="discountAmount" className="block text-sm font-medium text-gray-700">Discount Amount ($)</label>
                  <input
                    type="number" id="discountAmount" value={discountAmount}
                    onChange={(e) => { const val = parseFloat(e.target.value); setDiscountAmount(isNaN(val) ? 0 : Math.max(0, val)); setDiscountPercentage(0); }}
                    min="0" className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="discountPercentage" className="block text-sm font-medium text-gray-700">Discount Percentage (%)</label>
                  <input
                    type="number" id="discountPercentage" value={discountPercentage}
                    onChange={(e) => { const val = parseFloat(e.target.value); setDiscountPercentage(isNaN(val) ? 0 : Math.max(0, Math.min(100, val))); setDiscountAmount(0); }}
                    min="0" max="100" className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="paymentMethod" className="block text-sm font-medium text-gray-700">Payment Method</label>
                  <select
                    id="paymentMethod" value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}
                    className="mt-1 block w-full p-2 border rounded-md shadow-sm sm:text-sm"
                  >
                    <option value="cash">Cash</option>
                    <option value="credit">Credit</option>
                  </select>
                </div>
              </div>

              {/* Summary and Submit Button */}
              <div className="mt-8 flex flex-col md:flex-row justify-between items-center border-t border-gray-200 pt-6">
                <div className="mb-4 md:mb-0 text-lg font-bold text-gray-800">Total: ${totalAfterDiscount.toFixed(2)}</div>
                <div className="flex items-center">
                  <button
                    onClick={handleSubmitSale}
                    disabled={saleLoading || !selectedCustomerId || saleItems.length === 0}
                    className="px-6 py-3 border border-transparent rounded-md shadow-sm text-lg font-medium text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {saleLoading ? 'Processing...' : 'Confirm Sale'}
                  </button>
                </div>
              </div>

            </div>
          </div>

          {/* Users Table */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg mb-8">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">Users</h3>
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Email</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Role</th>
                    <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {users.map((user) => (
                    <tr key={user._id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{user.name}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.email}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        <select value={user.role} onChange={(e) => updateUserRole(user._id, e.target.value)} className="border rounded px-2 py-1 text-sm">
                          <option value="user">User</option>
                          <option value="admin">Admin</option>
                        </select>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                        <button onClick={() => deleteUser(user._id)} className="text-red-600 hover:text-red-900">Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Inventory Table */}
          <div className="bg-white shadow overflow-hidden sm:rounded-lg">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">Current Inventory</h3>
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Item Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Price</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {inventoryItems.map((item) => (
                    <tr key={item._id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{item.name}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">${item.price.toFixed(2)}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{item.quantity}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {inventoryItems.length === 0 && !inventoryLoading && (
                <p className="text-center py-4 text-gray-500">No items in inventory yet.</p>
              )}
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
